import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {rateCases,meanAccount,collisionCases} from './rate-models.js?v=20261023-physicscomplete01';
const txt=(x,y,s,n=15)=>`<text x="${x}" y="${y}" text-anchor="middle" font-family="sans-serif" font-size="${n}" fill="#f8f6f2">${s}</text>`;
export function showRates(kind='mean',t=null,reveal=false){
if(kind==='mean'){t??=rateCases[0];const a=meanAccount(t),max=Math.max(t.start,t.end)*1.2,y=v=>230-v/max*160;renderDiagram('Compare the two readings',t.title,`<svg class="lab-svg" viewBox="0 0 440 310" role="img" aria-label="${t.quantity}: ${t.start} at${t.t0} seconds and${t.end} at${t.t1} seconds. ${reveal?'Mean rate '+a.rate.toFixed(3)+' '+t.unit:'Calculate quantity change divided by elapsed time.'}"><path d="M65 55V230H390" fill="none" stroke="#b7c8d6"/>${txt(220,25,t.quantity,18)}<path d="M115 ${y(t.start)}L345 ${y(t.end)}" stroke="#ed8b78" stroke-width="3" stroke-dasharray="5 5"/>${[[115,t.start,t.t0],[345,t.end,t.t1]].map(([x,v,time])=>`<circle cx="${x}" cy="${y(v)}" r="6" fill="#ed8b78"/>${txt(x,y(v)-13,String(v))}${txt(x,255,time+' s')}`).join('')}${txt(220,285,reveal?`${a.change.toFixed(2)} ÷ ${a.elapsed} = ${a.rate.toFixed(3)} ${t.unit}`:'Two readings · one interval',16)}</svg><p class="diagram-caption">Dashed line joins two readings; it does not describe the instantaneous reaction rate.</p>`,'ILLUSTRATIVE MEASUREMENT RECORD · NOT CONTINUOUS DATA');return;}
t??=collisionCases[0];const surface=t.id==='surface',hot=t.id==='temperature',compressed=t.id==='pressure',dense=t.id==='concentration';let art='';
for(let side=0;side<2;side++){const left=side===0,x=left?25:240;art+=`<rect x="${x}" y="65" width="175" height="160" rx="16" fill="#b7c8d611" stroke="#b7c8d6"/>`+txt(x+87,45,left?'Before':'After',18);if(surface){const n=left?1:8,size=left?65:32.5;art+=Array.from({length:n},(_,i)=>`<rect x="${x+24+(i%4)*34}" y="${95+Math.floor(i/4)*55}" width="${size}" height="${size}" rx="3" fill="#ed8b7855" stroke="#ed8b78"/>`).join('');art+=txt(x+87,250,left?'1 cube · area 6a²':'8 cubes · area 12a²',13);}else{const n=left?8:dense?16:8,width=!left&&compressed?82:160;for(let i=0;i<n;i++){const px=x+15+(i%4)*(width-25)/4,py=90+Math.floor(i/4)*32;art+=`<circle cx="${px}" cy="${py}" r="7" fill="${i%2?'#b7c8d6':'#ed8b78'}"/><path d="M${px+8} ${py}h${!left&&hot?20:9}" stroke="#f8f6f2"/>`;}if(!left&&compressed)art+=`<path d="M${x+92} 70V220" stroke="#ed8b78" stroke-width="5"/>`;art+=txt(x+87,250,!left&&hot?'Same activation threshold':!left&&compressed?'Same count · half volume':!left&&dense?'Twice the count · same volume':'Fixed comparison',12);}}
renderDiagram('Change the conditions',t.title,`<svg class="lab-svg" viewBox="0 0 440 310" role="img" aria-label="${t.title}. Before and after symbolic comparison: ${t.change}. ${reveal?'Faster reaction: '+(t.reason==='energy'?'more frequent and more energetic collisions':t.reason==='surface'?'more collisions at exposed solid surface':'higher collision frequency'):'Predict the rate and mechanism.'}">${art}${txt(220,290,reveal?(t.reason==='energy'?'More frequent + more energetic collisions':t.reason==='surface'?'More surface collisions':'More frequent collisions'):'Predict before checking',15)}</svg><p class="diagram-caption">Symbolic snapshots and motion marks, not a molecular simulation or exact rate law.</p>`,'CONTROLLED COMPARISON · COLOUR IS SYMBOLIC');}
